// The hero: the Dragon Forge medallion as a real-time 3D object in a forge.
// - The coin face is the master artwork; relief, gold and lava come from textures
//   generated by tools/make-textures.py.
// - Drag to turn it, tap to strike it (sparks), or use the two buttons.
// - The medallion is positioned over the fallback <img>, so CSS controls the layout.
import {
  WebGLRenderer, Scene, PerspectiveCamera, Group, Mesh, CircleGeometry, LatheGeometry, SphereGeometry,
  PlaneGeometry, Vector2, Vector3, Matrix4, Quaternion, Ray, MeshStandardMaterial, MeshBasicMaterial, ShaderMaterial,
  LineBasicMaterial, TextureLoader, CanvasTexture, SRGBColorSpace, RepeatWrapping, PointLight, DirectionalLight,
  HemisphereLight, ACESFilmicToneMapping, PMREMGenerator, Color, BufferGeometry, BufferAttribute, Points,
  LineSegments, AdditiveBlending, BackSide, DoubleSide, MathUtils,
} from 'three';
import { EffectComposer } from 'three/addons/postprocessing/EffectComposer.js';
import { RenderPass } from 'three/addons/postprocessing/RenderPass.js';
import { UnrealBloomPass } from 'three/addons/postprocessing/UnrealBloomPass.js';
import { OutputPass } from 'three/addons/postprocessing/OutputPass.js';
import { damp, clamp, rng, loop, visibility, qualityTier } from './util.js';

const THICK = 0.15;

/* ---------- textures drawn in code ---------------------------------------- */
function knurlTexture() {
  const c = document.createElement('canvas');
  c.width = 64; c.height = 4;
  const g = c.getContext('2d');
  for (let x = 0; x < 64; x++) {
    const s = Math.sin((x / 64) * Math.PI * 2);
    const n = new Vector3(s * 0.75, 0, 1).normalize();
    g.fillStyle = `rgb(${Math.round((n.x * 0.5 + 0.5) * 255)},128,${Math.round((n.z * 0.5 + 0.5) * 255)})`;
    g.fillRect(x, 0, 1, 4);
  }
  const t = new CanvasTexture(c);
  t.wrapS = t.wrapT = RepeatWrapping;
  t.repeat.set(220, 1);
  return t;
}

function arcText(g, text, cx, cy, radius, centerAngle, font, color, outward = true, tracking = 1) {
  g.save();
  g.font = font;
  g.fillStyle = color;
  g.textAlign = 'center';
  g.textBaseline = 'middle';
  const widths = [...text].map((ch) => g.measureText(ch).width * tracking);
  const total = widths.reduce((a, b) => a + b, 0);
  const span = total / radius;
  let a = outward ? centerAngle - span / 2 : centerAngle + span / 2;
  [...text].forEach((ch, i) => {
    const w = widths[i] / radius;
    a += outward ? w / 2 : -w / 2;
    g.save();
    g.translate(cx + Math.cos(a) * radius, cy + Math.sin(a) * radius);
    g.rotate(outward ? a + Math.PI / 2 : a - Math.PI / 2);
    g.fillText(ch, 0, 0);
    g.restore();
    a += outward ? w / 2 : -w / 2;
  });
  g.restore();
}

function backTexture() {
  const size = 1024;
  const R = size / 2;
  const c = document.createElement('canvas');
  c.width = c.height = size;
  const g = c.getContext('2d');
  const base = g.createRadialGradient(R * 0.75, R * 0.6, R * 0.05, R, R, R);
  base.addColorStop(0, '#5a3d22');
  base.addColorStop(0.55, '#2f1f12');
  base.addColorStop(1, '#1b110a');
  g.fillStyle = base;
  g.fillRect(0, 0, size, size);
  // hammered texture
  const rand = rng(11);
  for (let i = 0; i < 2600; i++) {
    const x = rand() * size, y = rand() * size, r = 2 + rand() * 9;
    g.fillStyle = `rgba(${rand() > 0.5 ? '255,220,170' : '0,0,0'},${0.02 + rand() * 0.04})`;
    g.beginPath(); g.arc(x, y, r, 0, Math.PI * 2); g.fill();
  }
  const gold = '#f0bd72';
  g.strokeStyle = gold;
  g.lineWidth = 7; g.beginPath(); g.arc(R, R, R * 0.965, 0, Math.PI * 2); g.stroke();
  g.lineWidth = 5; g.beginPath(); g.arc(R, R, R * 0.735, 0, Math.PI * 2); g.stroke();
  g.lineWidth = 2; g.beginPath(); g.arc(R, R, R * 0.705, 0, Math.PI * 2); g.stroke();
  arcText(g, 'DRAGON FORGE DIGITAL', R, R, R * 0.85, -Math.PI / 2, '900 86px Cinzel, serif', gold, true, 1.08);
  arcText(g, 'BUILD IT · BRAND IT · AUTOMATE IT · OWN IT', R, R, R * 0.85, Math.PI / 2, '700 46px Cinzel, serif', gold, false, 1.02);
  arcText(g, '0110 1010', R, R, R * 0.85, Math.PI, '500 34px "IBM Plex Mono", monospace', '#c98a4a', true, 1.1);
  arcText(g, '1011 0100', R, R, R * 0.85, 0, '500 34px "IBM Plex Mono", monospace', '#c98a4a', true, 1.1);
  g.textAlign = 'center';
  g.textBaseline = 'middle';
  const mono = g.createLinearGradient(0, R * 0.55, 0, R * 1.45);
  mono.addColorStop(0, '#ffe2a8'); mono.addColorStop(0.5, '#f2b25e'); mono.addColorStop(1, '#a8652a');
  g.fillStyle = mono;
  g.font = '900 330px Cinzel, serif';
  g.fillText('DF', R, R * 0.97);
  g.fillStyle = '#d9a35e';
  g.font = '500 36px "IBM Plex Mono", monospace';
  g.fillText('EST. 2026 · WESTERN KENTUCKY', R, R * 1.32);
  const t = new CanvasTexture(c);
  t.colorSpace = SRGBColorSpace;
  return t;
}

/* ---------- the forge's light, for reflections ----------------------------- */
function forgeEnvironment(renderer) {
  const env = new Scene();
  const room = new Mesh(new SphereGeometry(20, 32, 16), new MeshBasicMaterial({ color: new Color(0.012, 0.009, 0.007), side: BackSide }));
  env.add(room);
  const panel = (w, h, color, pos, look = [0, 0, 0]) => {
    const m = new Mesh(new PlaneGeometry(w, h), new MeshBasicMaterial({ color, side: DoubleSide }));
    m.position.set(...pos); m.lookAt(...look); env.add(m);
  };
  panel(16, 6, new Color(9, 3.2, 0.7), [0, -9, 4]);          // the fire below
  panel(6, 6, new Color(2.6, 2.3, 2.0), [3, 8, 10]);         // soft key above the viewer
  panel(4, 10, new Color(1.6, 0.7, 0.25), [-12, 0, 4]);      // warm wall
  panel(5, 8, new Color(0.35, 0.45, 0.75), [11, 5, -8]);     // cool rim from behind
  const pmrem = new PMREMGenerator(renderer);
  const rt = pmrem.fromScene(env, 0.03);
  pmrem.dispose();
  return rt.texture;
}

/* ---------- embers --------------------------------------------------------- */
function embers(count) {
  const rand = rng(3);
  const seed = new Float32Array(count * 4);
  const size = new Float32Array(count);
  for (let i = 0; i < count; i++) {
    const near = rand() < 0.42;
    seed[i * 4] = near ? 0.5 + (rand() - 0.5) * 0.35 : rand();   // x across the screen (0..1); some near the coin
    seed[i * 4 + 1] = -4 + rand() * 5.5;                           // depth
    seed[i * 4 + 2] = 0.35 + rand() * 0.9;                         // rise speed
    seed[i * 4 + 3] = rand();                                      // phase
    size[i] = 0.6 + rand() * rand() * 3.2;
  }
  const geo = new BufferGeometry();
  geo.setAttribute('position', new BufferAttribute(new Float32Array(count * 3), 3));
  geo.setAttribute('aSeed', new BufferAttribute(seed, 4));
  geo.setAttribute('aSize', new BufferAttribute(size, 1));
  const mat = new ShaderMaterial({
    uniforms: {
      uTime: { value: 0 }, uBounds: { value: new Vector3(-4, 4, 0) }, uBoundsY: { value: new Vector2(-3, 3) },
      uCenterX: { value: 0 }, uDist: { value: 8 }, uScale: { value: 140 }, uHeat: { value: 1 },
    },
    vertexShader: /* glsl */`
      attribute vec4 aSeed;
      attribute float aSize;
      uniform float uTime, uDist, uScale, uCenterX;
      uniform vec3 uBounds;
      uniform vec2 uBoundsY;
      varying float vLife;
      varying float vSeed;
      void main() {
        float life = fract(aSeed.w + uTime * aSeed.z * 0.055);
        float depth = (uDist - aSeed.y) / uDist;
        float x = mix(uBounds.x, uBounds.y, aSeed.x);
        if (abs(aSeed.x - 0.5) < 0.18) x = uCenterX + (aSeed.x - 0.5) * 9.0;
        float y = mix(uBoundsY.x - 0.6, uBoundsY.y + 0.6, life);
        x += sin(uTime * 0.8 + aSeed.w * 40.0) * 0.18 * (0.4 + life) + sin(uTime * 0.31 + aSeed.x * 9.0) * 0.45 * life;
        vec3 p = vec3(x * depth, y * depth, aSeed.y);
        vLife = life;
        vSeed = aSeed.w;
        vec4 mv = modelViewMatrix * vec4(p, 1.0);
        gl_Position = projectionMatrix * mv;
        gl_PointSize = aSize * uScale / -mv.z * (1.0 - life * 0.55);
      }`,
    fragmentShader: /* glsl */`
      uniform float uTime, uHeat;
      varying float vLife;
      varying float vSeed;
      void main() {
        float d = length(gl_PointCoord - 0.5);
        float a = smoothstep(0.5, 0.0, d);
        a *= a;
        vec3 hot = vec3(1.0, 0.86, 0.55);
        vec3 mid = vec3(1.0, 0.38, 0.06);
        vec3 cold = vec3(0.45, 0.06, 0.01);
        vec3 col = mix(hot, mid, smoothstep(0.0, 0.45, vLife));
        col = mix(col, cold, smoothstep(0.55, 1.0, vLife));
        float fade = smoothstep(0.0, 0.06, vLife) * (1.0 - smoothstep(0.7, 1.0, vLife));
        float flicker = 0.7 + 0.3 * sin(uTime * 17.0 + vSeed * 80.0);
        gl_FragColor = vec4(col * a * fade * flicker * 2.4 * uHeat, 1.0);
      }`,
    transparent: true,
    depthWrite: false,
    blending: AdditiveBlending,
    toneMapped: false,
  });
  const pts = new Points(geo, mat);
  pts.frustumCulled = false;
  return pts;
}

/* ---------- sparks for the strike ----------------------------------------- */
// Streaks (line segments) with glowing heads (points) and a flash where the hammer lands.
const POINT_VS = /* glsl */`
  attribute vec3 aColor;
  attribute float aSize;
  uniform float uScale;
  varying vec3 vColor;
  void main() {
    vColor = aColor;
    vec4 mv = modelViewMatrix * vec4(position, 1.0);
    gl_Position = projectionMatrix * mv;
    gl_PointSize = aSize * uScale / -mv.z;
  }`;
const POINT_FS = /* glsl */`
  varying vec3 vColor;
  void main() {
    float d = length(gl_PointCoord - 0.5);
    float a = smoothstep(0.5, 0.0, d);
    gl_FragColor = vec4(vColor * a * a, 1.0);
  }`;

function sparks(max = 160) {
  const pos = new Float32Array(max * 6);
  const col = new Float32Array(max * 6);
  const geo = new BufferGeometry();
  geo.setAttribute('position', new BufferAttribute(pos, 3));
  geo.setAttribute('color', new BufferAttribute(col, 3));
  const lines = new LineSegments(geo, new LineBasicMaterial({ vertexColors: true, transparent: true, blending: AdditiveBlending, depthWrite: false, toneMapped: false }));
  lines.frustumCulled = false;

  // heads + one extra slot for the impact flash
  const hPos = new Float32Array((max + 1) * 3);
  const hCol = new Float32Array((max + 1) * 3);
  const hSize = new Float32Array(max + 1).fill(1);
  hSize[max] = 14;
  const hGeo = new BufferGeometry();
  hGeo.setAttribute('position', new BufferAttribute(hPos, 3));
  hGeo.setAttribute('aColor', new BufferAttribute(hCol, 3));
  hGeo.setAttribute('aSize', new BufferAttribute(hSize, 1));
  const hMat = new ShaderMaterial({ uniforms: { uScale: { value: 40 } }, vertexShader: POINT_VS, fragmentShader: POINT_FS, transparent: true, depthWrite: false, blending: AdditiveBlending, toneMapped: false });
  const heads = new Points(hGeo, hMat);
  heads.frustumCulled = false;
  lines.add(heads);

  const live = Array.from({ length: max }, () => ({ p: new Vector3(), v: new Vector3(), life: 0, max: 1 }));
  const flash = { p: new Vector3(), life: 0 };
  let cursor = 0;
  return {
    object: lines,
    setScale(v) { hMat.uniforms.uScale.value = v; },
    burst(at, normal, n = 90, rand = Math.random) {
      flash.p.copy(at).addScaledVector(normal, 0.02);
      flash.life = 1;
      for (let i = 0; i < n; i++) {
        const s = live[cursor]; cursor = (cursor + 1) % max;
        s.p.copy(at);
        const dir = new Vector3(rand() - 0.5, rand() - 0.2, rand() - 0.5).normalize().add(normal.clone().multiplyScalar(1.05)).normalize();
        s.v.copy(dir).multiplyScalar(2.4 + rand() * rand() * 7);
        s.max = s.life = 0.35 + rand() * 0.85;
      }
    },
    update(dt) {
      let any = flash.life > 0;
      for (let i = 0; i < max; i++) {
        const s = live[i];
        const o = i * 6;
        const h = i * 3;
        if (s.life <= 0) { pos.fill(0, o, o + 6); col.fill(0, o, o + 6); hCol.fill(0, h, h + 3); continue; }
        any = true;
        s.life -= dt;
        s.v.y -= 9.8 * 0.6 * dt;
        s.v.multiplyScalar(1 - 1.3 * dt);
        s.p.addScaledVector(s.v, dt);
        const t = Math.max(0, s.life / s.max);
        pos[o] = s.p.x; pos[o + 1] = s.p.y; pos[o + 2] = s.p.z;
        pos[o + 3] = s.p.x - s.v.x * 0.06; pos[o + 4] = s.p.y - s.v.y * 0.06; pos[o + 5] = s.p.z - s.v.z * 0.06;
        const r = 6 * t, g = 3.4 * t * t, b = 1.2 * t * t * t;
        col[o] = r; col[o + 1] = g; col[o + 2] = b;
        col[o + 3] = r * 0.25; col[o + 4] = g * 0.12; col[o + 5] = 0;
        hPos[h] = s.p.x; hPos[h + 1] = s.p.y; hPos[h + 2] = s.p.z;
        hCol[h] = 2.2 * t; hCol[h + 1] = 1.5 * t * t; hCol[h + 2] = 0.6 * t * t;
      }
      const f = max * 3;
      flash.life = Math.max(0, flash.life - dt * 3.2);
      const k = flash.life * flash.life;
      hPos[f] = flash.p.x; hPos[f + 1] = flash.p.y; hPos[f + 2] = flash.p.z;
      hCol[f] = 2.6 * k; hCol[f + 1] = 1.6 * k; hCol[f + 2] = 0.7 * k;
      geo.attributes.position.needsUpdate = true;
      geo.attributes.color.needsUpdate = true;
      hGeo.attributes.position.needsUpdate = true;
      hGeo.attributes.aColor.needsUpdate = true;
      return any;
    },
  };
}

/* ---------- background glow (screen space) --------------------------------- */
function backdrop() {
  const mat = new ShaderMaterial({
    uniforms: { uRes: { value: new Vector2(1, 1) }, uCenter: { value: new Vector2(0.7, 0.5) }, uRadius: { value: 300 }, uHeat: { value: 1 } },
    vertexShader: 'void main(){ gl_Position = vec4(position.xy, 0.9999, 1.0); }',
    fragmentShader: /* glsl */`
      uniform vec2 uRes, uCenter;
      uniform float uRadius, uHeat;
      void main() {
        vec2 p = gl_FragCoord.xy;
        float d = length((p - uCenter) / vec2(1.0, 0.92)) / uRadius;
        vec3 base = vec3(0.0036, 0.0028, 0.0021);
        vec3 halo = vec3(0.30, 0.085, 0.012) * exp(-d * d * 0.9) * (0.55 + 0.45 * uHeat);
        float floorGlow = exp(-pow((p.y / uRes.y) * 3.2, 2.0)) * exp(-pow((p.x - uCenter.x) / (uRes.x * 0.55), 2.0));
        vec3 fire = vec3(0.32, 0.07, 0.008) * floorGlow * (0.6 + 0.4 * uHeat);
        gl_FragColor = vec4(base + halo + fire, 1.0);
      }`,
    depthWrite: false,
    depthTest: false,
    toneMapped: false,
  });
  const quad = new Mesh(new PlaneGeometry(2, 2), mat);
  quad.frustumCulled = false;
  quad.renderOrder = -10;
  return quad;
}

/* ---------- the scene ------------------------------------------------------ */
export async function createHero(container, { reduce }) {
  const img = container.querySelector('.hero__fallback');
  const section = container.closest('.hero') || container;
  const tier = qualityTier();
  const renderer = new WebGLRenderer({ antialias: true, powerPreference: 'high-performance', alpha: false });
  const maxDpr = tier === 'low' ? 1.5 : tier === 'max' ? 2 : 1.75;
  renderer.setPixelRatio(Math.min(devicePixelRatio || 1, maxDpr));
  renderer.toneMapping = ACESFilmicToneMapping;
  renderer.toneMappingExposure = 1.05;
  renderer.setClearColor(0x0b0907, 1);
  const canvas = renderer.domElement;
  canvas.setAttribute('aria-hidden', 'true');
  canvas.setAttribute('tabindex', '-1');

  const scene = new Scene();
  scene.environment = forgeEnvironment(renderer);
  scene.environmentIntensity = 0.85;
  const camera = new PerspectiveCamera(28, 1, 0.1, 100);

  const loader = new TextureLoader();
  const load = (url) => new Promise((res, rej) => loader.load(url, res, undefined, rej));
  const base = new URL('../../img/', import.meta.url);
  const [faceTex, normalTex, masksTex] = await Promise.all([
    load(new URL('emblem-1024.webp', base).href),
    load(new URL('emblem-normal.webp', base).href),
    load(new URL('emblem-masks.webp', base).href),
    document.fonts ? Promise.all([document.fonts.load('900 80px Cinzel'), document.fonts.load('500 30px "IBM Plex Mono"')]).catch(() => {}) : null,
  ]);
  faceTex.colorSpace = SRGBColorSpace;
  const aniso = renderer.capabilities.getMaxAnisotropy();
  [faceTex, normalTex, masksTex].forEach((t) => { t.anisotropy = Math.min(8, aniso); });

  /* medallion */
  const coin = new Group();
  const tiltGroup = new Group();
  tiltGroup.add(coin);
  scene.add(tiltGroup);
  const glow = { value: 1.4 };
  const faceMat = new MeshStandardMaterial({
    map: faceTex, normalMap: normalTex, normalScale: new Vector2(1.15, 1.15), roughness: 1, metalness: 1, envMapIntensity: 1.25,
  });
  faceMat.onBeforeCompile = (shader) => {
    shader.uniforms.uMasks = { value: masksTex };
    shader.uniforms.uGlow = glow;
    shader.fragmentShader = shader.fragmentShader
      .replace('#include <common>', '#include <common>\nuniform sampler2D uMasks;\nuniform float uGlow;')
      .replace('#include <roughnessmap_fragment>', 'vec3 dfMask = texture2D(uMasks, vMapUv).rgb;\nfloat roughnessFactor = clamp(mix(0.84, 0.24, dfMask.r) - 0.25 * dfMask.g, 0.1, 1.0);')
      .replace('#include <metalnessmap_fragment>', 'float metalnessFactor = clamp(0.05 + 0.95 * dfMask.r + 0.35 * dfMask.g, 0.0, 1.0);')
      .replace('#include <emissivemap_fragment>', 'totalEmissiveRadiance = diffuseColor.rgb * (dfMask.b * uGlow + 0.07);');
  };
  const face = new Mesh(new CircleGeometry(1, 180), faceMat);
  face.position.z = THICK / 2;
  coin.add(face);

  const backTex = backTexture();
  const back = new Mesh(new CircleGeometry(1, 180), new MeshStandardMaterial({
    map: backTex, bumpMap: backTex, bumpScale: 3, metalness: 0.92, roughness: 0.36, envMapIntensity: 1.3,
  }));
  back.rotation.y = Math.PI;
  back.position.z = -THICK / 2;
  coin.add(back);

  const h = THICK / 2;
  const profile = [
    [0.992, -h - 0.001], [1.0, -h - 0.012], [1.022, -h - 0.016], [1.04, -h - 0.004], [1.05, -h + 0.02],
    [1.052, -h + 0.04], [1.052, h - 0.04], [1.05, h - 0.02], [1.04, h + 0.004], [1.022, h + 0.016], [1.0, h + 0.012], [0.992, h + 0.001],
  ].map(([r, y]) => new Vector2(r, y));
  const rimMat = new MeshStandardMaterial({ color: 0x8a5a2b, metalness: 1, roughness: 0.3, normalMap: knurlTexture(), normalScale: new Vector2(0.6, 0.6), envMapIntensity: 1.5 });
  const rim = new Mesh(new LatheGeometry(profile, 220), rimMat);
  rim.rotation.x = Math.PI / 2;
  coin.add(rim);

  /* lights */
  const fire = new PointLight(0xff6a1c, 26, 0, 2);
  fire.position.set(0.2, -2.1, 1.8);
  scene.add(fire);
  const sweep = new PointLight(0xffe0b0, 14, 0, 2);
  sweep.position.set(2, 1.6, 2.4);
  scene.add(sweep);
  const rimLight = new DirectionalLight(0x8fa6ff, 1.1);
  rimLight.position.set(-3, 2.5, -3);
  scene.add(rimLight);
  scene.add(new HemisphereLight(0x5a3a22, 0x0b0907, 0.35));

  /* particles + background */
  const emberPts = embers(tier === 'low' ? 420 : 950);
  scene.add(emberPts);
  const spark = sparks(180);
  scene.add(spark.object);
  const bg = backdrop();
  scene.add(bg);

  /* post-processing on capable devices */
  let composer = null;
  let bloom = null;
  const useBloom = tier !== 'low';
  if (useBloom) {
    composer = new EffectComposer(renderer);
    composer.addPass(new RenderPass(scene, camera));
    bloom = new UnrealBloomPass(new Vector2(256, 256), 0.62, 0.5, 0.86);
    composer.addPass(bloom);
    composer.addPass(new OutputPass());
  }

  /* layout: put the coin exactly where the fallback image sits */
  let W = 1, H = 1, dist = 8, center = new Vector2(), rpx = 200;
  const layout = () => {
    W = Math.max(1, container.clientWidth);
    H = Math.max(1, container.clientHeight);
    renderer.setSize(W, H, false);
    composer?.setSize(W, H);
    const cr = container.getBoundingClientRect();
    const ir = img.getBoundingClientRect();
    const cx = ir.left + ir.width / 2 - cr.left;
    const cy = ir.top + ir.height / 2 - cr.top;
    rpx = (ir.width / 2) * 0.985;
    const fullW = 2 * Math.max(cx, W - cx);
    const fullH = 2 * Math.max(cy, H - cy);
    camera.aspect = fullW / fullH;
    camera.setViewOffset(fullW, fullH, fullW / 2 - cx, fullH / 2 - cy, W, H);
    const tanHalf = Math.tan(MathUtils.degToRad(camera.fov / 2));
    dist = fullH / (2 * rpx * tanHalf);
    camera.position.set(0, 0, dist);
    camera.lookAt(0, 0, 0);
    camera.updateProjectionMatrix();
    const k = (2 * dist * tanHalf) / fullH;
    const u = emberPts.material.uniforms;
    u.uBounds.value.set(-cx * k - 0.6, (W - cx) * k + 0.6, 0);
    u.uBoundsY.value.set(-(H - cy) * k, cy * k);
    u.uDist.value = dist;
    u.uScale.value = (H / (2 * tanHalf)) * 0.012 * renderer.getPixelRatio();
    spark.setScale((H / (2 * tanHalf)) * 0.03 * renderer.getPixelRatio());
    const dpr = renderer.getPixelRatio();
    bg.material.uniforms.uRes.value.set(W * dpr, H * dpr);
    bg.material.uniforms.uCenter.value.set(cx * dpr, (H - cy) * dpr);
    bg.material.uniforms.uRadius.value = rpx * 1.25 * dpr;
    center.set(cx, cy);
  };

  /* interaction */
  const state = {
    spin: 0, spinVel: 0, mode: 'rest', target: 0,
    tiltX: 0, tiltY: 0, aimX: 0, aimY: 0,
    heat: 1, flash: 0, shake: 0, scroll: 0, interacting: 0,
  };
  const ray = new Ray();
  const inv = new Matrix4();
  const ndc = new Vector2();
  const hitPoint = (clientX, clientY) => {
    const r = canvas.getBoundingClientRect();
    ndc.set(((clientX - r.left) / r.width) * 2 - 1, -((clientY - r.top) / r.height) * 2 + 1);
    ray.origin.setFromMatrixPosition(camera.matrixWorld);
    ray.direction.set(ndc.x, ndc.y, 0.5).unproject(camera).sub(ray.origin).normalize();
    coin.updateWorldMatrix(true, false);
    inv.copy(coin.matrixWorld).invert();
    const local = ray.clone().applyMatrix4(inv);
    const t = -local.origin.z / local.direction.z;
    if (!(t > 0)) return null;
    const p = local.origin.clone().addScaledVector(local.direction, t);
    if (p.length() > 1.06) return null;
    return p.applyMatrix4(coin.matrixWorld);
  };

  const strike = (worldPoint) => {
    coin.updateWorldMatrix(true, false);
    const n = new Vector3(0, 0, 1).applyQuaternion(coin.getWorldQuaternion(new Quaternion()));
    const side = n.z >= 0 ? 1 : -1;           // sparks fly off whichever face looks at the viewer
    n.multiplyScalar(side);
    const at = worldPoint || new Vector3((Math.random() - 0.5) * 0.9, (Math.random() - 0.3) * 0.9, side * THICK / 2).applyMatrix4(coin.matrixWorld);
    spark.burst(at, n, reduce.matches ? 40 : 110);
    state.flash = 1;
    if (!reduce.matches) { state.shake = 1; state.spinVel += (Math.random() - 0.5) * 2.5; state.mode = 'free'; }
    wake();
  };
  const flip = () => {
    state.mode = 'target';
    state.target = Math.round(state.spin / Math.PI) * Math.PI + Math.PI;
    wake();
  };

  let drag = null;
  canvas.addEventListener('pointerdown', (e) => {
    if (!hitPoint(e.clientX, e.clientY)) return;
    drag = { x: e.clientX, y: e.clientY, start: state.spin, moved: false, lastX: e.clientX, lastT: performance.now() };
    canvas.setPointerCapture(e.pointerId);
    state.interacting = 1;
    wake();
  });
  canvas.addEventListener('pointermove', (e) => {
    if (drag) {
      const dx = e.clientX - drag.x;
      if (!drag.moved && Math.abs(dx) > 5) drag.moved = true;
      if (drag.moved) {
        const now = performance.now();
        const ddx = e.clientX - drag.lastX;
        const dts = Math.max(1, now - drag.lastT) / 1000;
        state.spin = drag.start + dx * (2.8 / Math.max(240, rpx * 2));
        state.spinVel = (ddx * (2.8 / Math.max(240, rpx * 2))) / dts;
        drag.lastX = e.clientX; drag.lastT = now;
        state.mode = 'drag';
      }
      return;
    }
    canvas.style.cursor = hitPoint(e.clientX, e.clientY) ? 'grab' : '';
  });
  const release = (e) => {
    if (!drag) return;
    const wasClick = !drag.moved;
    drag = null;
    state.interacting = 0;
    if (wasClick && e.type === 'pointerup') { state.mode = state.mode === 'drag' ? 'free' : state.mode; strike(hitPoint(e.clientX, e.clientY)); }
    else { state.mode = 'free'; state.spinVel = clamp(state.spinVel, -14, 14); }
    wake();
  };
  canvas.addEventListener('pointerup', release);
  canvas.addEventListener('pointercancel', release);
  section.addEventListener('pointermove', (e) => {
    if (e.pointerType !== 'mouse') return;
    state.aimX = clamp((e.clientX - (canvas.getBoundingClientRect().left + center.x)) / (W * 0.5), -1, 1);
    state.aimY = clamp((e.clientY - (canvas.getBoundingClientRect().top + center.y)) / (H * 0.5), -1, 1);
    wake();
  });
  section.addEventListener('pointerleave', () => { state.aimX = 0; state.aimY = 0; wake(); });

  const controls = section.querySelector('[data-hero-controls]');
  section.querySelector('[data-hero-strike]')?.addEventListener('click', () => strike(null));
  section.querySelector('[data-hero-flip]')?.addEventListener('click', flip);

  /* the frame */
  let visible = true;
  let time = 0;
  let frames = 0;
  let slowFrames = 0;
  const still = () => reduce.matches;
  const step = (dt) => {
    if (!still()) time += dt;
    frames++;

    // forge flicker
    const f = 0.84 + 0.08 * Math.sin(time * 7.3) + 0.05 * Math.sin(time * 13.1 + 1.3) + 0.03 * Math.sin(time * 23.7 + 0.5);
    state.flash = Math.max(0, state.flash - dt * 2.4);
    state.heat = f + state.flash * 1.4;
    fire.intensity = 26 * state.heat;
    glow.value = 1.25 * f + state.flash * 2.2;
    emberPts.material.uniforms.uTime.value = time;
    emberPts.material.uniforms.uHeat.value = 0.85 + state.flash * 0.6;
    bg.material.uniforms.uHeat.value = state.heat;

    // a slow highlight sweeping across the relief
    if (!still()) {
      sweep.position.set(Math.sin(time * 0.45) * 2.6, 1.4 + Math.sin(time * 0.31) * 0.6, 2.4);
    }

    // spin: drag / free / settle / target
    if (state.mode === 'free') {
      state.spin += state.spinVel * dt;
      state.spinVel *= Math.exp(-2.4 * dt);
      if (Math.abs(state.spinVel) < 1.2) { state.mode = 'target'; state.target = Math.round(state.spin / Math.PI) * Math.PI; }
    } else if (state.mode === 'target') {
      const k = 34, c = 2 * Math.sqrt(k) * 0.9;
      state.spinVel += ((state.target - state.spin) * k - state.spinVel * c) * dt;
      state.spin += state.spinVel * dt;
      if (Math.abs(state.target - state.spin) < 0.0005 && Math.abs(state.spinVel) < 0.01) { state.spin = state.target; state.spinVel = 0; state.mode = 'rest'; }
    }

    // aim toward the pointer, idle float, scroll parallax
    const idle = still() ? 0 : 1;
    state.tiltX = damp(state.tiltX, state.aimY * 0.32 + Math.sin(time * 0.5) * 0.05 * idle, 4, dt);
    state.tiltY = damp(state.tiltY, state.aimX * 0.42 + Math.sin(time * 0.37) * 0.09 * idle, 4, dt);
    const sr = section.getBoundingClientRect();
    state.scroll = clamp(-sr.top / Math.max(1, sr.height), 0, 1);
    tiltGroup.rotation.set(state.tiltX + state.scroll * 0.7, state.tiltY, Math.sin(time * 0.3) * 0.025 * idle);
    tiltGroup.position.y = Math.sin(time * 0.6) * 0.035 * idle + state.scroll * 0.9;
    coin.rotation.y = state.spin;

    // strike shake
    state.shake = Math.max(0, state.shake - dt * 4);
    const s = state.shake * state.shake * 0.02;
    camera.position.set((Math.random() - 0.5) * s, (Math.random() - 0.5) * s, dist);

    const sparksAlive = spark.update(dt);
    if (composer) composer.render(dt); else renderer.render(scene, camera);

    // adapt if the device struggles
    if (frames > 20 && frames < 140 && dt > 1 / 38) slowFrames++;
    if (frames === 140 && slowFrames > 40 && tier !== 'max') {
      if (composer) { composer = null; }
      renderer.setPixelRatio(1);
      layout();
    }
    return sparksAlive;
  };

  let busy = false;
  const ticker = loop((dt) => {
    busy = step(dt);
  }, () => visible && (!still() || state.mode !== 'rest' || state.interacting || busy || state.flash > 0));
  function wake() { ticker.wake(); }

  container.prepend(canvas);
  layout();
  new ResizeObserver(() => { layout(); wake(); }).observe(container);
  addEventListener('scroll', () => { if (still()) return; wake(); }, { passive: true });
  visibility(section, (v) => { visible = v; if (v) wake(); });
  reduce.addEventListener?.('change', wake);

  // first frame, then reveal
  step(1 / 60);
  container.classList.add('is-live');
  controls?.removeAttribute('hidden');
  wake();
  return { renderer };
}
